	static boolean exists(long txn) throws IOException {
		int metadata = openDatabase(txn, METADATA_DATABASE, false);
		if (metadata < 0) {
			if (openDatabase(txn, PAGES_DATABASE, false) >= 0 || openDatabase(txn, DELTAS_DATABASE, false) >= 0) {
				throw new IOException("Incomplete persistent adjacency database set");
			}
			return false;
		}
		validateFormat(txn, metadata);
		if (openDatabase(txn, PAGES_DATABASE, false) < 0 || openDatabase(txn, DELTAS_DATABASE, false) < 0) {
			throw new IOException("Persistent adjacency is missing a page or delta database");
		}
		return true;
	}

	/** Opens handles in the caller's setup transaction; initialize only after migration has completed. */
